import gzip,base64,json,subprocess,sys,time,zipfile
from pathlib import Path
from IPython.display import display,HTML
A=Path('/kaggle/working/rascar_v15')
for name,source in json.loads(gzip.decompress(base64.b64decode(''))).items():(A/name).write_text(source)
download_output('shapodev/rascar-v14-geometry-quality-and-learned-ranking/versions/9','rascar_v14/yolo26_clean/yolo26s.pt',A/'weights/yolo26s.pt')
assert len(pd.read_csv(A/'image_paths.csv'))==170
workers15={}
def start15(name,args):
 workers15[name]=subprocess.Popen([sys.executable,'-u']+args,stdout=open(A/f'{name}.log','w'),stderr=subprocess.STDOUT,cwd=A)
start15('hand25',[str(A/'train_hand_specialist.py'),'2026-10-25','0'])
start15('hand26',[str(A/'train_hand_specialist.py'),'2026-10-26','1'])
while any(p.poll() is None for p in workers15.values()):
 print('HAND_PROGRESS',[(fit,pd.read_csv(A/'hand_specialist'/fit/'train/results.csv').shape[0] if (A/'hand_specialist'/fit/'train/results.csv').exists() else 0) for fit in ['2026-10-25','2026-10-26']],flush=True);time.sleep(30)
print('FOLD_STATUS',{k:p.returncode for k,p in workers15.items()},flush=True)
for k,p in workers15.items():
 if p.returncode:print(k,(A/f'{k}.log').read_text()[-2500:],flush=True)
assert all(p.returncode==0 for p in workers15.values())
start15('handall',[str(A/'train_hand_specialist.py'),'all','0'])
start15('pose',[str(A/'extract_pose.py')])
while any(p.poll() is None for p in workers15.values()):
 print('FINAL_PROGRESS',{k:p.poll() for k,p in workers15.items()},'epochs',len(pd.read_csv(A/'hand_specialist/all/train/results.csv')) if (A/'hand_specialist/all/train/results.csv').exists() else 0,flush=True);time.sleep(30)
print('V15_ALL_FINISHED',{k:p.returncode for k,p in workers15.items()},flush=True)
for k,p in workers15.items():
 if p.returncode:print(k,(A/f'{k}.log').read_text()[-2500:],flush=True)
with zipfile.ZipFile(A/'hands_pose_results.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in A.glob('hand_specialist/**/*.csv'):z.write(p,p.relative_to(A))
 for p in A.glob('hand_specialist/**/manifest.json'):z.write(p,p.relative_to(A))
 if (A/'pose_references.csv').exists():z.write(A/'pose_references.csv','pose_references.csv')
display(HTML('<a download="hands_pose_results.zip" href="data:application/octet-stream;base64,'+base64.b64encode((A/'hands_pose_results.zip').read_bytes()).decode()+'">Download hand specialist and pose results</a>'))